ems'=>'елементи','minimum input length for searching post links3'=>'3','minutes ago'=>'хвилини тому','monthly'=>'щомісяця','months ago'=>'кілька місяців тому','name'=>'ім\'я','needs update'=>'потребує оновлення','never'=>'ніколи','not installed'=>'не встановлено','of'=>'з','off'=>'вимкнено','review'=>'огляд' . "\0" . 'відгуки' . "\0" . 'notFound','sitemaps'=>'карти сайту','statically'=>'статично','this is an XML Sitemap, meant to be consumed by search engines like Google or Bing.'=>'це XML-карта сайту, призначена для використання пошуковими системами, такими як Google або Bing.','to analyze a competitor site.'=>'щоб аналізувати сайт конкурента.','to see your Site Score.'=>'щоб побачити оцінку вашого сайту.','unknown'=>'невідомий','upgrade to %1$s'=>'оновіться до %1$s','upgrading to %1$s'=>'оновлення до %1$s','very easy'=>'дуже легко','vote'=>'голос' . "\0" . 'голоси' . "\0" . 'голосів','weekly'=>'щотижня','yearly'=>'щороку','years ago'=>'кілька років тому']];
